import $ from 'jquery';

// PC版
const parent = document.querySelectorAll('.js-pc-navi');

const node = Array.prototype.slice.call(parent, 0);

node.forEach((element) => {
  element.addEventListener(
    'mouseover',
    () => {
      element.querySelector('.open-navi').classList.add('active');
    },
    false
  );
  element.addEventListener(
    'mouseout',
    () => {
      element.querySelector('.open-navi').classList.remove('active');
    },
    false
  );
});

// SP版
$(
  (function () {
    $('.js-sp-navi').on('click', () => {
      $('.sp-navi').toggleClass('open'), $('.js-sp-navi').toggleClass('open');
    });
  })()
);
