import $ from 'jquery';

window.onload = function () {
  $(() => {
    if (document.getElementById('js-infographics')) {
      // カウントアップ
      $(window).on('load scroll', () => {
        $('.js-count').each(function () {
          const txtPos = $(this).offset().top;
          const scroll = $(window).scrollTop();
          const windowHeight = $(window).height();
          if (scroll > txtPos - windowHeight + windowHeight / 5) {
            if ($('.js-num', this).attr('data-num').indexOf('.') > -1) {
              var rounding = 1;
            } else {
              var rounding = 0;
            }
            $('.js-num', this).numerator({
              easing: 'linear', // カウントアップの動き
              duration: 1000, // カウントアップの時間
              toValue: $('.js-num', this).attr('data-num'), // カウントアップする数値
              rounding, // 小数点以下の桁数（初期値：0）
            });
          }
        });
      });
      // 円グラフ
      const color_01 = 'rgb(34, 180, 255)';
      const color_02 = 'rgb(172, 250, 235)';
      const color_03 = 'rgb(230, 230, 230)';
      const item04 = document.querySelector('#item-04_chart').getContext('2d');
      const item06 = document.querySelector('#item-06_chart').getContext('2d');
      const item07 = document.querySelector('#item-07_chart').getContext('2d');
      const item10 = document.querySelector('#item-10_chart').getContext('2d');
      const item11 = document.querySelector('#item-11_chart').getContext('2d');
      new Chart(item04, {
        type: 'pie',
        data: {
          labels: ['', ''],
          datasets: [
            {
              label: false,
              data: [85,15],
              backgroundColor: [color_01, color_02],
            },
          ],
        },
        options: {
          plugins: {
            legend: {
              display: false,
            },
            tooltip: {
              enabled: false,
            },
          },
          responsive: true,
        },
      }),
        new Chart(item06, {
          type: 'pie',
          data: {
            labels: ['', ''],
            datasets: [
              {
                label: false,
                data: [50, 50],
                backgroundColor: [color_01, color_02],
              },
            ],
          },
          options: {
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                enabled: false,
              },
            },
            responsive: true,
          },
        }),
        new Chart(item07, {
          type: 'pie',
          data: {
            labels: ['', ''],
            datasets: [
              {
                label: false,
                data: [100, 0],
                backgroundColor: [color_01, color_02],
              },
            ],
          },
          options: {
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                enabled: false,
              },
            },
            responsive: true,
          },
        }),
        new Chart(item10, {
          type: 'pie',
          data: {
            labels: ['', ''],
            datasets: [
              {
                label: false,
                data: [100, 0],
                backgroundColor: [color_01, color_02],
              },
            ],
          },
          options: {
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                enabled: false,
              },
            },
            responsive: true,
          },
        }),
        new Chart(item11, {
          type: 'pie',
          data: {
            labels: ['', ''],
            datasets: [
              {
                label: false,
                data: [87.5, 12.5],
                backgroundColor: [color_01, color_02],
              },
            ],
          },
          options: {
            plugins: {
              legend: {
                display: false,
              },
              tooltip: {
                enabled: false,
              },
            },
            responsive: true,
          },
        });
    }
  });
};
